import {CAFE_MENU as M,CAFE_UPGRADES as U,CAFE_NAMES as N,CAFE_DAY_MS} from './cafe-config.js';
import {cafeMissing,cafeOrderValue,cafeReserved,cafeCapacity,kneadPulse} from './cafe-state.js';
const button=(action,label,disabled=false,extra='')=>`<button data-cafe-action="${action}" ${disabled?'disabled':''} ${extra}>${label}</button>`;
export function cafeShell(){return `<section class="cafe-hud" aria-label="밀구름 카페 운영"><header class="cafe-header"><div><span class="cafe-eyebrow">도름이의 밀구름</span><h2>작은 베이커리</h2></div><div class="cafe-wallet"><strong data-coins>0</strong><span>게임 코인</span></div>${button('pause','쉬기',false,'aria-label="영업 일시정지"')}${button('close','×',false,'aria-label="카페 운영 닫기"')}</header><div class="cafe-dayline"><strong data-day></strong><span data-clock></span><span data-served></span></div><div class="cafe-orders" data-orders aria-label="주문서"></div><div class="cafe-workspace"><div class="cafe-notice" data-notice role="status" aria-live="polite"></div><div data-panel></div></div></section>`;}
function menu(s,kind){return `<div class="cafe-menu">${Object.entries(M).filter(([,m])=>m.kind===kind).map(([id,m])=>button(kind==='bread'?'bread':'drink',`<span>${m.icon}</span><strong>${m.label}</strong><small>판매 ${m.price} − 재료 ${m.cost} = ${m.price-m.cost}</small>`,cafeReserved(s,kind)>=cafeCapacity(s,kind),`data-recipe="${id}"`)).join('')}</div>`;}
function stock(s){return `<div class="cafe-stock"><strong>진열대</strong>${Object.entries(M).map(([id,m])=>`<span class="${s.stock[id]?'has-stock':''}">${m.icon} ${s.stock[id]}${s.qualityStock[id]?'✦':''}</span>`).join('')}<details><summary>남는 음식 정리</summary>${Object.entries(M).filter(([id])=>s.stock[id]).map(([id,m])=>button('remove',`${m.label} 한 개 내리기`,false,`data-recipe="${id}"`)).join('')}<p>만드는 동안 돈은 들지 않아요. 재료값은 팔 때 정산해요.</p></details></div>`;}
function stations(s,tab){const d=s.dough,o=s.oven,c=s.drink;return `<nav class="cafe-tabs" aria-label="작업대">${[['bread','반죽'],['oven','오븐'],['drink','음료']].map(([id,label])=>button('tab',`${label}${id==='oven'&&o?' ●':id==='drink'&&c?' ●':''}`,false,`data-tab="${id}" aria-pressed="${tab===id}"`)).join('')}</nav><div class="cafe-stations"><section class="cafe-station" data-station="bread" ${tab==='bread'?'':'data-mobile-hidden'}><h3>01　반죽 작업대</h3>${d?`<div class="cafe-job"><strong>${M[d.recipeId].icon} ${M[d.recipeId].label} · ${d.folds}/3번 접기</strong>${d.folds<3?`<p>초록 띠에 바늘이 오면 눌러요</p><div class="cafe-meter knead"><span></span><i data-needle></i></div>${button('fold',d.folds?'한 번 더 접기':'반죽 접기',false,`data-job="${d.id}"`)}<small>놓쳐도 괜찮아요. 두 번 맞히면 더 폭신해져요</small>`:button('load',o?'오븐 한 칸이 비길 기다려요':'반죽을 오븐에 넣기',!!o,`data-job="${d.id}"`)}</div>`:menu(s,'bread')}</section><section class="cafe-station" data-station="oven" ${tab==='oven'?'':'data-mobile-hidden'}><h3>02　${s.upgrades.warmOven?'황동':'작은'} 오븐 · 한 칸</h3>${o?`<div class="cafe-job"><strong>${M[o.recipeId].icon} ${M[o.recipeId].label}</strong><div class="cafe-meter"><b data-progress="oven"></b></div><p data-job-time="oven"></p>${button('display','집게로 꺼내 진열하기',s.activeMs<o.readyMs,`data-job="${o.id}"`)}<small>다 구워진 뒤 3초 안에 꺼내면 폭신함을 지켜요. 늦어도 타지 않아요</small></div>`:`<div class="cafe-idle-station"><strong>지금은 빈 오븐이에요</strong><p>반죽을 넣고, 굽는 동안 음료를 준비해 보세요</p>${button('tab','반죽 만들러 가기',false,'data-tab="bread"')}</div>`}</section><section class="cafe-station" data-station="drink" ${tab==='drink'?'':'data-mobile-hidden'}><h3>03　음료 작업대</h3>${c?`<div class="cafe-job"><strong>${M[c.recipeId].icon} ${M[c.recipeId].label}</strong><div class="cafe-meter"><b data-progress="drink"></b></div><p data-job-time="drink"></p>${button('collect','따뜻할 때 컵 받기',s.activeMs<c.readyMs,`data-job="${c.id}"`)}<small>완성 후 3초 안에 받으면 향긋함 +1</small></div>`:menu(s,'drink')}</section></div>${stock(s)}<div class="cafe-foot">${button('shop','가게 꾸미기')}<span>한 번에 빵 ${cafeReserved(s,'bread')}/${cafeCapacity(s,'bread')} · 음료 ${cafeReserved(s,'drink')}/2</span></div>`;}
export function cafePanel(s,{running,tab='bread',shop=false}={}){
 if(shop)return `<div class="cafe-shop"><h3>내 손으로 키우는 가게</h3><p>고르는 동안 장사는 잠깐 쉬어요</p>${Object.entries(U).map(([id,u])=>`<article><div><strong>${u.label}</strong><p>${u.description}</p></div>${button('buy',s.upgrades[id]?'우리 가게에 있어요':`${u.cost} 코인`,s.upgrades[id]||s.coins<u.cost,`data-upgrade="${id}"`)}</article>`).join('')}${button('back','작업대로 돌아가기')}</div>`;
 if(s.phase==='summary')return `<div class="cafe-summary"><span>오늘도 고소한 하루</span><h3>${s.today.served}팀에게 내어준 마음</h3><dl><div><dt>판매한 음식</dt><dd>${s.today.revenue}</dd></div><div><dt>사용한 재료값</dt><dd>− ${s.today.materials}</dd></div><div><dt>빠른 손길과 정성 팁</dt><dd>+ ${s.today.tips}</dd></div><div class="total"><dt>오늘 남긴 코인</dt><dd>${s.today.revenue-s.today.materials+s.today.tips}</dd></div></dl><p>${s.day===1?'내일은 빵 두 개를 찾는 손님도 와요. 오븐이 바쁜 동안 다음 반죽을 준비해 볼까요?':'같은 시간이라도 준비 순서를 바꾸면 더 여유로워져요.'}</p>${button('next','다음 날 준비하기')}${button('shop','가게 꾸미기')}${button('gift','선물 케이크 만들기')}</div>`;
 if(s.phase==='idle'||!running)return `<div class="cafe-welcome"><span>${s.phase==='idle'?`${s.day}일째 아침`:'잠깐 쉬는 중'}</span><h3>${s.phase==='idle'?'오늘은 어떤 빵을 구울까요?':'주문과 반죽은 기다려 줘요'}</h3><p>손님 주문을 보고 빵과 음료를 준비해요. 굽는 동안 다른 일을 하면 더 여유로워요.</p><div class="cafe-rules"><span>① 주문 읽기</span><span>② 직접 조리</span><span>③ 진열 · 서빙</span></div>${button('start',s.phase==='idle'?'오늘 가게 열기':'장사 이어하기')}${button('shop','가게 꾸미기')}${button('gift','선물 케이크 만들기')}<small>실제 돈을 쓰지 않아요 · 닫으면 시간이 멈춰요</small></div>`;
 return stations(s,tab);
}
export function cafeOrders(s){if(!s.orders.length)return `<div class="cafe-order empty"><strong>${s.phase==='closing'?'마지막 음식을 정리해요':'주문을 기다리는 중'}</strong><span>${s.phase==='running'?'미리 반죽하거나 가게를 둘러봐요':'한 주문씩 천천히 해도 괜찮아요'}</span></div>`;return s.orders.map(o=>{const waiting=s.activeMs>=o.shownMs,missing=cafeMissing(s,o),v=cafeOrderValue(o);return `<article class="cafe-order ${!missing.length&&waiting?'ready':''}"><div class="cafe-order-title"><strong>${N[o.residentId]}</strong><span>${waiting?(s.activeMs-o.shownMs<=45000?'빠른 팁 +2':'천천히 준비해요'):'걸어오는 중'}</span></div><div class="cafe-order-items">${Object.entries(o.items).map(([id,n])=>`<span>${M[id].icon} ${M[id].label}${n>1?' ×'+n:''}</span>`).join('')}</div><div class="cafe-order-end"><small>판매 ${v.price} · 재료 ${v.cost}</small>${button('serve',!waiting?'잠깐만요':missing.length?'준비 중':'서빙하기',!waiting||!!missing.length,`data-order="${o.id}"`)}</div><small>${missing.length?missing.map(x=>`${M[x.id].label} ${x.count}개`).join(' · ')+' 더 필요해요':'접시에 모두 준비됐어요'}</small></article>`;}).join('');}
export function updateCafeMotion(root,s,extraMs=0){const time=s.activeMs+extraMs;root.querySelector('[data-clock]').textContent=s.phase==='idle'?'3분의 작은 영업':s.phase==='summary'?'오늘 영업 끝':s.phase==='closing'?'마지막 주문 마무리':`${Math.max(0,Math.ceil((CAFE_DAY_MS-time)/1000))}초 · 새 손님 마감까지`;const needle=root.querySelector('[data-needle]');if(needle)needle.style.left=`${kneadPulse({...s,activeMs:time})*100}%`;for(const [k,j]of [['oven',s.oven],['drink',s.drink]]){const bar=root.querySelector(`[data-progress="${k}"]`),label=root.querySelector(`[data-job-time="${k}"]`);if(bar&&j)bar.style.width=`${Math.min(100,Math.max(0,(time-j.startedMs)/j.durationMs*100))}%`;if(label&&j)label.textContent=time<j.readyMs?`${Math.ceil((j.readyMs-time)/1000)}초 남았어요`:time-j.readyMs<=3000?'지금이 딱 좋아요! ✦':'완성됐어요. 천천히 받아 주세요';}}
